182	/**
183	 * Handles policy updates for standard tools (Shell, Info, etc.), including
184	 * session-level and persistent approvals.
185	 */
186	async function handleStandardPolicyUpdate(
187	  tool: AnyDeclarativeTool,
188	  outcome: ToolConfirmationOutcome,
189	  confirmationDetails: SerializableConfirmationDetails | undefined,
190	  messageBus: MessageBus,
191	  persistScope?: 'workspace' | 'user',
192	  toolInvocation?: AnyToolInvocation,
193	  config?: Config,
194	): Promise<void> {
195	  if (
196	    outcome === ToolConfirmationOutcome.ProceedAlways ||
197	    outcome === ToolConfirmationOutcome.ProceedAlwaysAndSave
198	  ) {
199	    const options: PolicyUpdateOptions =
200	      toolInvocation?.getPolicyUpdateOptions?.(outcome) || {};
201	
202	    if (!options.commandPrefix && confirmationDetails?.type === 'exec') {
203	      options.commandPrefix = confirmationDetails.rootCommands;
204	    } else if (!options.argsPattern && confirmationDetails?.type === 'edit') {
205	      const filePath = config
206	        ? makeRelative(confirmationDetails.filePath, config.getTargetDir())
207	        : confirmationDetails.filePath;
208	      options.argsPattern = buildFilePathArgsPattern(filePath);
209	    }
210	
211	    await messageBus.publish({
212	      type: MessageBusType.UPDATE_POLICY,
213	      toolName: tool.name,
214	      persist: outcome === ToolConfirmationOutcome.ProceedAlwaysAndSave,
215	      persistScope,
216	      ...options,
217	    });
218	  }
219	}
